const materialLines=list=>list.map(e=>`[${e.id}] ${e.name}：${e.text}${e.note?`\n（资料整理说明，非原文引述：${e.note}）`:''}`).join('\n');
// —— 关键词检索：字符二元组上的 BM25，本地计算，不依赖外部服务 ——
